// Regenerates lib/src/data/*.dart from tool/data. Run from the package root:
//
//   dart run tool/generate_data.dart
//
// See tool/data/SOURCES.md for where the data comes from.
import 'dart:convert';
import 'dart:io';

void main() {
  _provinces();
  _bayrams();
}

void _provinces() {
  final list =
      jsonDecode(File('tool/data/il_ilce.json').readAsStringSync())
          as List<dynamic>;
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/generate_data.dart from tool/data/il_ilce.json.',
    )
    ..writeln(
      '// Source: T.C. İçişleri Bakanlığı, e-İçişleri Mülki İdare '
      'Bölümleri (2026-10-22).',
    )
    ..writeln('// Do not edit by hand.')
    ..writeln()
    ..writeln(
      '/// (plate code, province name, districts) for the 81 provinces.',
    )
    ..writeln('const List<(int, String, List<String>)> provinceData = [');
  for (final item in list.cast<Map<String, dynamic>>()) {
    final districts = (item['districts'] as List<dynamic>)
        .map((d) => "'$d'")
        .join(', ');
    out.writeln("  (${item['plate']}, '${item['name']}', [$districts]),");
  }
  out.writeln('];');
  File('lib/src/data/provinces_data.dart').writeAsStringSync(out.toString());
}

void _bayrams() {
  final lines = File('tool/data/bayramlar.csv').readAsLinesSync().skip(1);
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/generate_data.dart from tool/data/bayramlar.csv.',
    )
    ..writeln(
      '// Source: Diyanet İşleri Başkanlığı dini günler takvimi '
      '(2026-10-22).',
    )
    ..writeln('// Do not edit by hand.')
    ..writeln()
    ..writeln(
      '/// (isKurban, year, month, day) of the first day of each '
      'bayram.',
    )
    ..writeln('const List<(bool, int, int, int)> bayramData = [');
  for (final line in lines) {
    if (line.trim().isEmpty) continue;
    final cells = line.split(',');
    final date = cells[2].split('-').map(int.parse).toList();
    out.writeln(
      '  (${cells[1] == 'kurban'}, ${date[0]}, ${date[1]}, '
      '${date[2]}),',
    );
  }
  out.writeln('];');
  File('lib/src/data/bayram_data.dart').writeAsStringSync(out.toString());
}
